Here's how to write modern MSTest tests for your `DataFetcher`:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;
    private readonly MockHttpMessageHandler _handler;
    private readonly DataFetcher _sut;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
        _handler = new MockHttpMessageHandler();
        var client = new HttpClient(_handler) { BaseAddress = new Uri("https://example.com") };
        _sut = new DataFetcher(client);
    }

    [TestMethod]
    public async Task FetchAsync_SuccessResponse_ReturnsContent()
    {
        // Arrange
        _handler.ResponseContent = "hello world";

        // Act
        var result = await _sut.FetchAsync("https://example.com/data",
            _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_WithTimeout_CompletesInTime()
    {
        _handler.ResponseContent = "fast";

        var result = await _sut.FetchAsync("https://example.com/data",
            _testContext.CancellationToken);

        Assert.IsNotNull(result);
    }

    [TestMethod]
    public async Task FetchAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = new CancellationTokenSource();
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _sut.FetchAsync("https://example.com/data", cts.Token));
    }

    [TestMethod]
    public async Task FetchAsync_NonSuccessStatusCode_ThrowsHttpRequestException()
    {
        _handler.StatusCode = System.Net.HttpStatusCode.NotFound;

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _sut.FetchAsync("https://example.com/missing",
                _testContext.CancellationToken));
    }
}

// Minimal fake handler for testing
internal sealed class MockHttpMessageHandler : HttpMessageHandler
{
    public string ResponseContent { get; set; } = string.Empty;
    public System.Net.HttpStatusCode StatusCode { get; set; } = System.Net.HttpStatusCode.OK;

    protected override Task<HttpResponseMessage> SendAsync(
        HttpRequestMessage request, CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();

        var response = new HttpResponseMessage(StatusCode)
        {
            Content = new StringContent(ResponseContent)
        };
        return Task.FromResult(response);
    }
}
```

**Key patterns demonstrated:**

1. **`TestContext` via constructor** — injected for access to `CancellationToken` (MSTest 3.6+)
2. **`[Timeout(5000)]` + `_testContext.CancellationToken`** — cooperative timeout that actually cancels the async operation (fixes MSTEST0045)
3. **`Assert.ThrowsExactlyAsync<T>`** — modern exception testing (not `[ExpectedException]`)
4. **Cancellation test** — verifies the token is properly forwarded by pre-cancelling a `CancellationTokenSource`
5. **Custom `HttpMessageHandler`** — avoids real HTTP calls without needing a mocking library

Always flow `_testContext.CancellationToken` into your awaited calls so `[Timeout]` can actually abort stuck tests rather than just reporting failure after the fact.
